  function loadSave(){try{return Object.assign({name:'',wins:{},best:{},sound:true,lifetime:{},achievements:{},seen:{},xp:0,cosmetic:'classic'},JSON.parse(localStorage.getItem('verdantGuardSave'))||{});}catch{return{name:'',wins:{},best:{},sound:true,lifetime:{},achievements:{},seen:{},xp:0,cosmetic:'classic'};}}
