  function beginGame(){const name=ui.playerName.value.trim()||'Guardian';saved.name=name;selectedModifiers=[...document.querySelectorAll('[data-modifier]:checked')].map(x=>x.dataset.modifier);if(selectedMode==='daily'){const seed=Number(new Date().toISOString().slice(0,10).replaceAll('-',''));selectedMap=['meadow','ruins','thornmaze'][seed%3];selectedModifiers=[['swift'],['armored'],['scarcity','swift']][seed%3];}selectedCosmetic=ui.cosmeticSelect.value;saved.cosmetic=selectedCosmetic;save();unlockAudio();ui.guardName.textContent=`${name}'s `;const secret=document.createElement('span');secret.className='secret-guard';secret.textContent='Guard';ui.guardName.appendChild(secret);guardClicks=0;ui.mapName.innerHTML=`${maps[selectedMap].name} · ${maps[selectedMap].difficulty} · <span class="mode-badge">${modeNames[selectedMode]}</span>`;ui.startScreen.classList.add('hidden');reset();playTone(420,.12,'triangle');}
  function clearBuild(){state.selected=null;document.querySelectorAll('.tower-card').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}
  function clearSelections(){state.selectedTower=null;state.selectedEnemy=null;state.movingTower=false;ui.towerActions.classList.add('hidden');ui.enemyInfo.classList.add('hidden');}
