  function selectTower(type,force=false){if(!force&&state.selected===type){clearBuild();clearSelections();idleInfo();return;}clearSelections();state.selected=type;document.querySelectorAll('.tower-card').forEach(b=>{const on=b.dataset.tower===type;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});const s=towers[type];ui.selectedInfo.innerHTML=`<span>${s.label} · ${s.cost} credits</span><small>${s.desc}. Click open grass to place.</small>`;}
  function towerStats(t){const base=towers[t.type],level=t.level||1,mul=1+(level-1)*.32;let range=base.range*(1+(level-1)*.1),damage=base.damage*mul,rate=base.rate*Math.pow(.9,level-1),splash=base.splash,chain=base.chain,slow=base.slow,poison=base.poison;if(t.specialization==='rapid')rate*=.6;if(t.specialization==='piercing')damage*=2;if(t.specialization==='sniper')range*=1.45;if(t.specialization==='meteor')splash=85;if(t.specialization==='blizzard')range*=1.25;if(t.specialization==='shatter')damage*=1.65;if(t.specialization==='siege')splash=95;if(t.specialization==='cluster')rate*=.65;if(t.specialization==='venom')damage*=1.8;if(t.specialization==='wide')range*=1.55;if(t.specialization==='storm')chain=6;if(t.specialization==='surge')damage*=1.75;for(const z of zones){if(Math.hypot(t.x-z.x,t.y-z.y)<z.r){if(z.type==='range')range*=1.25;if(z.type==='damage')damage*=1.25;}}for(const ally of state.towers){if(ally!==t&&ally.type==='support'&&Math.hypot(t.x-ally.x,t.y-ally.y)<towerStatsSimple(ally).range){damage*=ally.specialization==='radiant'?1.25:1.12+(ally.level-1)*.05;rate*=.86;}}return{...base,range,damage,rate,splash,chain,slow,poison};}
  function towerStatsSimple(t){const b=towers[t.type],l=t.level||1;return{...b,range:b.range*(1+(l-1)*.1)};}
  function selectPlaced(t){if(state.selectedTower===t){clearSelections();idleInfo();return;}clearBuild();state.selectedEnemy=null;ui.enemyInfo.classList.add('hidden');state.selectedTower=t;state.movingTower=false;ui.towerActions.classList.remove('hidden');refreshTowerPanel();}
  function refreshTowerPanel(){const t=state.selectedTower;if(!t)return;const s=towerStats(t),refund=Math.floor(t.spent*.6),upgrade=t.level<3?Math.floor(towers[t.type].cost*(.55+t.level*.2)):0;ui.selectedInfo.innerHTML=`<span>${s.label} · Level ${t.level}${t.specialization?` · ${specializations[t.type].find(x=>x[0]===t.specialization)?.[1]||''}`:''}</span><small>Damage ${Math.round(s.damage)} · Range ${Math.round(s.range)}${towers[t.type].support?' · Support aura':''}</small>`;ui.moveTowerButton.textContent='Move tower';ui.sellTowerButton.textContent=`Sell · ${refund}`;ui.upgradeTowerButton.textContent=t.level>=3?'Max level':`Upgrade · ${upgrade}`;ui.specializeTowerButton.classList.toggle('hidden',t.level<3||!!t.specialization);ui.specializeTowerButton.disabled=state.waveActive||state.gameOver;ui.targetButton.textContent=`Target: ${t.targetMode}`;for(const b of [ui.moveTowerButton,ui.sellTowerButton,ui.upgradeTowerButton])b.disabled=state.waveActive||state.gameOver;ui.upgradeTowerButton.disabled||=t.level>=3||state.money<upgrade;ui.targetButton.disabled=towers[t.type].support;}
  function selectEnemy(e){if(state.selectedEnemy===e){clearSelections();idleInfo();return;}clearBuild();state.selectedTower=null;state.movingTower=false;ui.towerActions.classList.add('hidden');ui.enemyInfo.classList.add('hidden');state.selectedEnemy=e;ui.selectedInfo.innerHTML=`<span>${enemies[e.type].name} inspected</span><small>The description follows it on the battlefield</small>`;}
  function updateUI(){ui.money.textContent=state.money;ui.health.textContent=Math.max(0,Math.ceil(state.health));ui.healthBar.style.width=`${Math.max(0,state.health)}%`;ui.lives.textContent=state.lives;ui.score.textContent=state.score;ui.wave.textContent=Number.isFinite(state.maxWaves)?`${state.wave} / ${state.maxWaves}`:`${state.wave} / ∞`;ui.waveButton.disabled=state.waveActive||state.wave>=state.maxWaves||state.gameOver;ui.waveButton.textContent=state.waveActive?'Wave in progress':state.wave>=state.maxWaves?'All waves cleared':`Start wave ${state.wave+1}`;if(state.selectedTower)refreshTowerPanel();}
  function announce(text){ui.announcement.textContent=text;ui.announcement.classList.remove('hidden');clearTimeout(announce.t);announce.t=setTimeout(()=>ui.announcement.classList.add('hidden'),1500);}
  function enemyType(wave,index,total){if((wave===state.maxWaves||wave%10===0)&&index===total-1)return['boss','shieldboss','broodboss'][Math.floor(wave/10)%3];if(wave>=7&&index%6===4)return'healer';if(wave>=6&&index%5===3)return'splitter';if(wave>=5&&index%5===2)return'regen';if(wave>=4&&index%4===1)return'armored';if(wave>=3&&index%3===2)return'runner';return'crawler';}
  function waveRoster(wave){if(wave===state.wave+1&&state.cheatNextRoster)return state.cheatNextRoster;const total=5+wave*2+(state?.modifiers?.includes('swift')?Math.ceil(wave*.7):0),counts={};for(let i=0;i<total;i++){let type=enemyType(wave,i,total);if(state?.modifiers?.includes('armored')&&type==='crawler'&&i%3===0)type='armored';counts[type]=(counts[type]||0)+1;}return counts;}
  function updatePreview(){ui.previewDescription.classList.add('hidden');if(state.wave>=state.maxWaves){ui.previewEnemies.textContent='All waves completed';return;}const counts=waveRoster(state.wave+1);ui.previewEnemies.innerHTML=Object.entries(counts).filter(([,n])=>n>0).map(([k,n])=>`<button class="preview-enemy" data-enemy-type="${k}" style="--enemy-color:${enemies[k].color}"><i></i>${enemies[k].name} × ${n}</button>`).join('')||'No enemies';}
  function showPreviewDescription(type,button){if(button.classList.contains('active')){button.classList.remove('active');ui.previewDescription.classList.add('hidden');return;}const s=enemies[type];ui.previewEnemies.querySelectorAll('.preview-enemy').forEach(b=>b.classList.toggle('active',b===button));ui.previewDescription.innerHTML=`<b>${s.name}</b>${enemyDescriptions[type]} ${s.ability}. Leak damage: ${s.leakDamage}.`;ui.previewDescription.classList.remove('hidden');}
  function startWave(){if(state.waveActive||state.gameOver||state.wave>=state.maxWaves)return;state.movingTower=false;state.wave++;state.waveActive=true;const roster=state.cheatNextRoster||waveRoster(state.wave);state.spawnQueue=Object.entries(roster).flatMap(([type,n])=>Array(Math.max(0,Number(n)||0)).fill(type));state.cheatNextRoster=null;state.toSpawn=state.spawnQueue.length;state.spawned=0;state.spawnTimer=.15;announce(`Wave ${state.wave} incoming`);playTone(240,.18,'sawtooth');updateUI();updatePreview();}
  function makeEnemy(type,x=path[0].x,y=path[0].y,seg=0,scale=1){const s=enemies[type],base=(34+state.wave*15)*maps[selectedMap].mult*scale,hp=base*s.hp*(state.modifiers.includes('armored')?1.12:1);return{x,y,seg,type,hp,maxHp:hp,shield:s.shield?hp*s.shield:0,maxShield:s.shield?hp*s.shield:0,speed:(48+state.wave*3)*s.speed*(state.modifiers.includes('swift')?1.18:1),radius:s.boss?20:scale<1?8:type==='armored'?14:11,reward:Math.round((8+state.wave)*s.reward*scale*(state.modifiers.includes('scarcity')?.65:1)),slow:0,poison:0,poisonDps:0,healTimer:1.5,abilityTimer:3,trapTimer:0,split:s.split&&scale===1,boss:!!s.boss};}
  function spawnEnemy(){const type=state.spawnQueue.shift()||'crawler';state.enemies.push(makeEnemy(type));saved.seen[type]=true;save();state.spawned++;}
  function distSeg(px,py,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((px-a.x)*dx+(py-a.y)*dy)/(dx*dx+dy*dy)));return Math.hypot(px-(a.x+t*dx),py-(a.y+t*dy));}
  function canPlace(x,y,ignore=null){if(state.freePlacement)return x>=0&&x<=canvas.width&&y>=0&&y<=canvas.height;if(x<28||x>canvas.width-28||y<28||y>canvas.height-28)return false;if(path.some((p,i)=>i&&distSeg(x,y,path[i-1],p)<48))return false;if(obstacles.some(o=>Math.hypot(x-o.x,y-o.y)<o.r+26))return false;return state.towers.every(t=>t===ignore||Math.hypot(x-t.x,y-t.y)>56);}
  function place(x,y){const s=towers[state.selected];if(!s||state.gameOver)return;if(state.modifiers.includes('single')&&state.usedTowerTypes.length&&state.usedTowerTypes[0]!==state.selected){announce(`One tower type: use ${towers[state.usedTowerTypes[0]].label}`);return;}if(state.money<s.cost){announce('Not enough credits');return;}if(!canPlace(x,y)){announce('Choose open grass');return;}state.money-=s.cost;state.towers.push({x,y,type:state.selected,cool:Math.random()*.2,level:1,targetMode:'First',spent:s.cost,specialization:null});if(!state.usedTowerTypes.includes(state.selected))state.usedTowerTypes.push(state.selected);state.stats.towersBuilt++;state.effects.push({x,y,life:.45,color:s.color});playTone(520,.07);updateUI();}
  function handleField(x,y){if(state.pickingFeature){ui.cheatFeatureX.value=Math.round(x);ui.cheatFeatureY.value=Math.round(y);state.pickingFeature=false;ui.cheatPanel.classList.remove('hidden');announce(`Position selected: ${Math.round(x)}, ${Math.round(y)}`);return;}if(state.selected){place(x,y);return;}if(state.movingTower&&state.selectedTower){if(!canPlace(x,y,state.selectedTower)){announce('Choose open grass');return;}state.selectedTower.x=x;state.selectedTower.y=y;state.movingTower=false;refreshTowerPanel();announce('Tower moved');return;}const t=state.towers.find(v=>Math.hypot(x-v.x,y-v.y)<=26);if(t){selectPlaced(t);return;}const e=state.enemies.find(v=>Math.hypot(x-v.x,y-v.y)<=v.radius+8);if(e){selectEnemy(e);return;}clearSelections();idleInfo();}
  function toggleMove(){if(!state.selectedTower||state.waveActive)return;state.movingTower=!state.movingTower;ui.moveTowerButton.textContent=state.movingTower?'Cancel move':'Move tower';if(state.movingTower)ui.selectedInfo.innerHTML='<span>Choose a new position</span><small>Click open grass to move this tower</small>';else refreshTowerPanel();}
